let file = """{"version":3,"file":"AboutPanel-C8eW8wx2.js","names":["$t","$t"],"sources":["../../src/components/common/DeviceInfo.vue","../../src/components/common/DeviceInfo.vue","../../src/components/common/systemStatsColumns.ts","../../src/composables/useCopySystemInfo.ts","../../src/components/common/SystemStatsPanel.vue","../../src/components/common/SystemStatsPanel.vue","../../src/stores/aboutPanelStore.ts","../../src/components/dialog/content/setting/AboutPanel.vue","../../src/components/dialog/content/setting/AboutPanel.vue"],"sourcesContent":["<template>\n  <div class=\"grid grid-cols-2 gap-2\">\n    <template v-for=\"col in deviceColumns\" :key=\"col.field\">\n      <div class=\"font-medium\">\n        {{ col.header }}\n      </div>\n      <div>\n        {{ formatValue(props.device[col.field], col.field) }}\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { DeviceStats } from '@/platform/remote/comfyui/types'\nimport { formatSize } from '@/utils/formatUtil'\n\nconst props = defineProps<{\n  device: DeviceStats\n}>()\n\nconst deviceColumns: { field: keyof DeviceStats; header: string }[] = [\n  { field: 'name', header: 'Name' },\n  { field: 'type', header: 'Type' },\n  { field: 'vram_total', header: 'VRAM Total' },\n  { field: 'vram_free', header: 'VRAM Free' },\n  { field: 'torch_vram_total', header: 'Torch VRAM Total' },\n  { field: 'torch_vram_free', header: 'Torch VRAM Free' }\n]\n\nconst formatValue = (value: string | number, field: string) => {\n  if (\n    ['vram_total', 'vram_free', 'torch_vram_total', 'torch_vram_free'].includes(\n      field\n    )\n  ) {\n    const num = Number(value)\n    if (Number.isFinite(num)) {\n      return formatSize(num)\n    }\n    return value\n  }\n  return value\n}\n</script>\n","<template>\n  <div class=\"grid grid-cols-2 gap-2\">\n    <template v-for=\"col in deviceColumns\" :key=\"col.field\">\n      <div class=\"font-medium\">\n        {{ col.header }}\n      </div>\n      <div>\n        {{ formatValue(props.device[col.field], col.field) }}\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { DeviceStats } from '@/platform/remote/comfyui/types'\nimport { formatSize } from '@/utils/formatUtil'\n\nconst props = defineProps<{\n  device: DeviceStats\n}>()\n\nconst deviceColumns: { field: keyof DeviceStats; header: string }[] = [\n  { field: 'name', header: 'Name' },\n  { field: 'type', header: 'Type' },\n  { field: 'vram_total', header: 'VRAM Total' },\n  { field: 'vram_free', header: 'VRAM Free' },\n  { field: 'torch_vram_total', header: 'Torch VRAM Total' },\n  { field: 'torch_vram_free', header: 'Torch VRAM Free' }\n]\n\nconst formatValue = (value: string | number, field: string) => {\n  if (\n    ['vram_total', 'vram_free', 'torch_vram_total', 'torch_vram_free'].includes(\n      field\n    )\n  ) {\n    const num = Number(value)\n    if (Number.isFinite(num)) {\n      return formatSize(num)\n    }\n    return value\n  }\n  return value\n}\n</script>\n","import { isCloud } from '@/platform/distribution/types'\nimport type { SystemStats } from '@/platform/remote/comfyui/types'\nimport { formatCommitHash, formatSize } from '@/utils/formatUtil'\n\nconst frontendCommit = __COMFYUI_FRONTEND_COMMIT__\n\ntype SystemInfoKey = keyof SystemStats['system']\n\nexport type SystemStatsColumn = Readonly<{\n  field: SystemInfoKey\n  headerKey: string\n  format?: (value: string) => string\n  formatNumber?: (value: number) => string\n  getValue?: () => string\n}>\n\nconst localColumns = [\n  { field: 'argv', headerKey: 'g.systemStatsArguments' },\n  { field: 'embedded_python', headerKey: 'g.systemStatsEmbeddedPython' },\n  {\n    field: 'installed_templates_version',\n    headerKey: 'g.systemStatsTemplatesVersion'\n  },\n  { field: 'os', headerKey: 'g.systemStatsOS' },\n  { field: 'python_version', headerKey: 'g.systemStatsPythonVersion' },\n  { field: 'pytorch_version', headerKey: 'g.systemStatsPyTorchVersion' },\n  {\n    field: 'ram_free',\n    headerKey: 'g.systemStatsRAMFree',\n    formatNumber: formatSize\n  },\n  {\n    field: 'ram_total',\n    headerKey: 'g.systemStatsRAMTotal',\n    formatNumber: formatSize\n  }\n] as const satisfies readonly SystemStatsColumn[]\n\nconst cloudColumns = [\n  { field: 'cloud_version', headerKey: 'g.systemStatsCloudVersion' },\n  {\n    field: 'comfyui_frontend_version',\n    headerKey: 'g.systemStatsFrontendVersion',\n    getValue: () => frontendCommit,\n    format: formatCommitHash\n  },\n  {\n    field: 'comfyui_version',\n    headerKey: 'g.systemStatsComfyUIVersion',\n    format: formatCommitHash\n  },\n  {\n    field: 'workflow_templates_version',\n    headerKey: 'g.systemStatsTemplatesVersion'\n  }\n] as const satisfies readonly SystemStatsColumn[]\n\nexport const systemStatsColumns: readonly SystemStatsColumn[] = isCloud\n  ? cloudColumns\n  : localColumns\n\nexport function getColumnDisplayValue(\n  stats: SystemStats,\n  column: SystemStatsColumn\n): string | number | boolean | undefined {\n  const systemInfo = {\n    ...stats.system,\n    argv: stats.system.argv.join(' ')\n  }\n  const value = column.getValue ? column.getValue() : systemInfo[column.field]\n  if (column.formatNumber && typeof value === 'number') {\n    return column.formatNumber(value)\n  }\n  if (column.format && typeof value === 'string') {\n    return column.format(value)\n  }\n  if (Array.isArray(value)) return undefined\n  return value\n}\n","import { toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport {\n  getColumnDisplayValue,\n  systemStatsColumns\n} from '@/components/common/systemStatsColumns'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { t } from '@/i18n'\nimport type { SystemStats } from '@/platform/remote/comfyui/types'\nimport { formatSize } from '@/utils/formatUtil'\n\nfunction formatSystemInfoText(stats: SystemStats): string {\n  const lines: string[] = ['## System Info']\n\n  for (const col of systemStatsColumns) {\n    const display = getColumnDisplayValue(stats, col)\n    if (display !== undefined && display !== '') {\n      lines.push(`${t(col.headerKey)}: ${display}`)\n    }\n  }\n\n  if (stats.devices.length > 0) {\n    lines.push('')\n    lines.push('## Devices')\n    for (const device of stats.devices) {\n      lines.push(`- ${device.name} (${device.type})`)\n      lines.push(`  VRAM Total: ${formatSize(device.vram_total)}`)\n      lines.push(`  VRAM Free: ${formatSize(device.vram_free)}`)\n      lines.push(`  Torch VRAM Total: ${formatSize(device.torch_vram_total)}`)\n      lines.push(`  Torch VRAM Free: ${formatSize(device.torch_vram_free)}`)\n    }\n  }\n\n  return lines.join('\\n')\n}\n\nexport function useCopySystemInfo(stats: MaybeRefOrGetter<SystemStats>) {\n  const { copyToClipboard } = useCopyToClipboard()\n\n  function copySystemInfo() {\n    return copyToClipboard(formatSystemInfoText(toValue(stats)))\n  }\n\n  return { copySystemInfo }\n}\n","<template>\n  <div class=\"system-stats\">\n    <div class=\"mb-6\">\n      <div class=\"mb-4 flex items-center gap-2\">\n        <h2 class=\"text-2xl font-semibold\">\n          {{ $t('g.systemInfo') }}\n        </h2>\n        <Button variant=\"secondary\" @click=\"copySystemInfo\">\n          <i class=\"pi pi-copy\" />\n          {{ $t('g.copySystemInfo') }}\n        </Button>\n      </div>\n      <div class=\"grid grid-cols-2 gap-2\">\n        <template v-for=\"col in systemStatsColumns\" :key=\"col.field\">\n          <div :class=\"cn('font-medium', isOutdated(col) && 'text-danger-100')\">\n            {{ $t(col.headerKey) }}\n          </div>\n          <div :class=\"cn(isOutdated(col) && 'text-danger-100')\">\n            {{ getColumnDisplayValue(stats, col) }}\n          </div>\n        </template>\n      </div>\n    </div>\n\n    <template v-if=\"hasDevices\">\n      <div class=\"my-4 border-t border-interface-stroke\" />\n\n      <div>\n        <h2 class=\"mb-4 text-2xl font-semibold\">\n          {{ $t('g.devices') }}\n        </h2>\n        <Tabs\n          v-if=\"stats.devices.length > 1\"\n          :default-value=\"String(stats.devices[0].index)\"\n        >\n          <TabsList variant=\"bordered\" class=\"mb-4\">\n            <TabsTrigger\n              v-for=\"device in stats.devices\"\n              :key=\"device.index\"\n              :value=\"String(device.index)\"\n            >\n              {{ device.name }}\n            </TabsTrigger>\n          </TabsList>\n          <TabsContent\n            v-for=\"device in stats.devices\"\n            :key=\"device.index\"\n            :value=\"String(device.index)\"\n          >\n            <DeviceInfo :device=\"device\" />\n          </TabsContent>\n        </Tabs>\n        <DeviceInfo v-else :device=\"stats.devices[0]\" />\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport DeviceInfo from '@/components/common/DeviceInfo.vue'\nimport type { SystemStatsColumn } from '@/components/common/systemStatsColumns'\nimport {\n  getColumnDisplayValue,\n  systemStatsColumns\n} from '@/components/common/systemStatsColumns'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tabs from '@/components/ui/tabs/Tabs.vue'\nimport TabsContent from '@/components/ui/tabs/TabsContent.vue'\nimport TabsList from '@/components/ui/tabs/TabsList.vue'\nimport TabsTrigger from '@/components/ui/tabs/TabsTrigger.vue'\nimport { useCopySystemInfo } from '@/composables/useCopySystemInfo'\nimport type { SystemStats } from '@/platform/remote/comfyui/types'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { stats } = defineProps<{\n  stats: SystemStats\n}>()\n\nconst hasDevices = computed(() => stats.devices.length > 0)\n\nconst { copySystemInfo } = useCopySystemInfo(() => stats)\n\nfunction isOutdated(column: SystemStatsColumn): boolean {\n  if (column.field !== 'installed_templates_version') return false\n  const installed = stats.system.installed_templates_version\n  const required = stats.system.required_templates_version\n  return !!installed && !!required && installed !== required\n}\n</script>\n","<template>\n  <div class=\"system-stats\">\n    <div class=\"mb-6\">\n      <div class=\"mb-4 flex items-center gap-2\">\n        <h2 class=\"text-2xl font-semibold\">\n          {{ $t('g.systemInfo') }}\n        </h2>\n        <Button variant=\"secondary\" @click=\"copySystemInfo\">\n          <i class=\"pi pi-copy\" />\n          {{ $t('g.copySystemInfo') }}\n        </Button>\n      </div>\n      <div class=\"grid grid-cols-2 gap-2\">\n        <template v-for=\"col in systemStatsColumns\" :key=\"col.field\">\n          <div :class=\"cn('font-medium', isOutdated(col) && 'text-danger-100')\">\n            {{ $t(col.headerKey) }}\n          </div>\n          <div :class=\"cn(isOutdated(col) && 'text-danger-100')\">\n            {{ getColumnDisplayValue(stats, col) }}\n          </div>\n        </template>\n      </div>\n    </div>\n\n    <template v-if=\"hasDevices\">\n      <div class=\"my-4 border-t border-interface-stroke\" />\n\n      <div>\n        <h2 class=\"mb-4 text-2xl font-semibold\">\n          {{ $t('g.devices') }}\n        </h2>\n        <Tabs\n          v-if=\"stats.devices.length > 1\"\n          :default-value=\"String(stats.devices[0].index)\"\n        >\n          <TabsList variant=\"bordered\" class=\"mb-4\">\n            <TabsTrigger\n              v-for=\"device in stats.devices\"\n              :key=\"device.index\"\n              :value=\"String(device.index)\"\n            >\n              {{ device.name }}\n            </TabsTrigger>\n          </TabsList>\n          <TabsContent\n            v-for=\"device in stats.devices\"\n            :key=\"device.index\"\n            :value=\"String(device.index)\"\n          >\n            <DeviceInfo :device=\"device\" />\n          </TabsContent>\n        </Tabs>\n        <DeviceInfo v-else :device=\"stats.devices[0]\" />\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport DeviceInfo from '@/components/common/DeviceInfo.vue'\nimport type { SystemStatsColumn } from '@/components/common/systemStatsColumns'\nimport {\n  getColumnDisplayValue,\n  systemStatsColumns\n} from '@/components/common/systemStatsColumns'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tabs from '@/components/ui/tabs/Tabs.vue'\nimport TabsContent from '@/components/ui/tabs/TabsContent.vue'\nimport TabsList from '@/components/ui/tabs/TabsList.vue'\nimport TabsTrigger from '@/components/ui/tabs/TabsTrigger.vue'\nimport { useCopySystemInfo } from '@/composables/useCopySystemInfo'\nimport type { SystemStats } from '@/platform/remote/comfyui/types'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { stats } = defineProps<{\n  stats: SystemStats\n}>()\n\nconst hasDevices = computed(() => stats.devices.length > 0)\n\nconst { copySystemInfo } = useCopySystemInfo(() => stats)\n\nfunction isOutdated(column: SystemStatsColumn): boolean {\n  if (column.field !== 'installed_templates_version') return false\n  const installed = stats.system.installed_templates_version\n  const required = stats.system.required_templates_version\n  return !!installed && !!required && installed !== required\n}\n</script>\n","import { defineStore } from 'pinia'\nimport { computed } from 'vue'\n\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport type { AboutPageBadge } from '@/types/comfy'\nimport { electronAPI } from '@/utils/envUtil'\nimport { formatCommitHash } from '@/utils/formatUtil'\n\nimport { useExtensionStore } from './extensionStore'\nimport { useSystemStatsStore } from './systemStatsStore'\n\nexport const useAboutPanelStore = defineStore('aboutPanel', () => {\n  const frontendVersion = __COMFYUI_FRONTEND_VERSION__\n  const extensionStore = useExtensionStore()\n  const systemStatsStore = useSystemStatsStore()\n  const { staticUrls } = useExternalLink()\n  const coreVersion = computed(\n    () => systemStatsStore.systemStats?.system.comfyui_version ?? ''\n  )\n  const templatesVersion = computed(\n    () => systemStatsStore.systemStats?.system.installed_templates_version ?? ''\n  )\n  const requiredTemplatesVersion = computed(\n    () => systemStatsStore.systemStats?.system.required_templates_version ?? ''\n  )\n  const isTemplatesOutdated = computed(\n    () =>\n      templatesVersion.value !== '' &&\n      requiredTemplatesVersion.value !== '' &&\n      templatesVersion.value !== requiredTemplatesVersion.value\n  )\n\n  const coreBadges = computed<AboutPageBadge[]>(() => [\n    // In electron, the ComfyUI is packaged without the git repo,\n    // so the python server's API doesn't have the version info.\n    {\n      label: `ComfyUI ${\n        isDesktop\n          ? 'v' + electronAPI().getComfyUIVersion()\n          : formatCommitHash(coreVersion.value)\n      }`,\n      url: isCloud ? staticUrls.comfyOrg : staticUrls.github,\n      icon: isCloud ? 'pi pi-cloud' : 'pi pi-github'\n    },\n    {\n      label: `ComfyUI_frontend v${frontendVersion}`,\n      url: staticUrls.githubFrontend,\n      icon: 'pi pi-github'\n    },\n    ...(templatesVersion.value\n      ? [\n          {\n            label: `Templates v${templatesVersion.value}`,\n            url: 'https://pypi.org/project/comfyui-workflow-templates/',\n            icon: 'pi pi-book',\n            ...(isTemplatesOutdated.value\n              ? { severity: 'danger' as const }\n              : {})\n          }\n        ]\n      : []),\n    {\n      label: 'Discord',\n      url: staticUrls.discord,\n      icon: 'pi pi-discord'\n    },\n    { label: 'ComfyOrg', url: staticUrls.comfyOrg, icon: 'pi pi-globe' }\n  ])\n\n  const allBadges = computed<AboutPageBadge[]>(() => [\n    ...coreBadges.value,\n    ...extensionStore.extensions.flatMap((e) => e.abou